rule native_xor_variadic_positive_values {
  strings:
    $loop = { 8B 4A 04 83 C2 04 85 C9 7C ?? 32 CB 88 0E 46 4F 85 FF }
  condition:
    $loop
}

rule x86_unrolled_byte_xor_to_stack {
  strings:
    $decoder = { 0F B6 50 ?? 80 F1 ?? 80 F2 ?? 88 4C 24 ??
                 0F B6 48 ?? 88 54 24 ?? 0F B6 50 ??
                 80 F1 ?? 80 F2 ?? 88 4C 24 ?? }
  condition:
    uint16(0) == 0x5a4d and $decoder
}
